package dev.redstoneengineering.block;import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.*;import net.minecraft.world.level.block.state.properties.IntegerProperty;import net.minecraft.world.phys.BlockHitResult;public class PressureRegulatorBlock extends Block{public static final IntegerProperty SETPOINT=IntegerProperty.create("setpoint",1,4);public PressureRegulatorBlock(Properties p){super(p);registerDefaultState(stateDefinition.any().setValue(SETPOINT,2));}@Override public MapCodec<PressureRegulatorBlock> codec(){return RedstoneEngineering.PRESSURE_REGULATOR_CODEC.value();}@Override protected void createBlockStateDefinition(StateDefinition.Builder<Block,BlockState>b){b.add(SETPOINT);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int n=s.getValue(SETPOINT)%4+1;l.setBlock(p,s.setValue(SETPOINT,n),Block.UPDATE_CLIENTS);if(l instanceof net.minecraft.server.level.ServerLevel sl)PneumaticNetwork.recompute(sl,p);pl.displayClientMessage(Component.literal("Pressure regulator setpoint="+(n*25)+"/100"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}